const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s);const flavors=[{color:'#73b5d6',name:'BLEU<br>DE NUIT<br><i>N° SÉRIE</i>',copy:'Bleu de nuit, la première encre reprend les reflets du port.'},{color:'#9fce96',name:'VERT<br>DE NUIT<br><i>N° SÉRIE</i>',copy:'Vert de brume, un pigment clair inspiré de la lumière sur le métal.'},{color:'#e7d47a',name:'OR<br>DES QUAIS<br><i>N° SÉRIE</i>',copy:'Or des quais, un jaune chaud pour les dernières lueurs du soir.'}];let selected=0;function choose(n){selected=(n+3)%3;const f=flavors[selected],num=String(selected+1).padStart(2,'0');document.documentElement.style.setProperty('--accent',f.color);$('#productTitle').innerHTML=f.name;$('#productCopy').textContent=f.copy;$('#productNumber').textContent='NOTTURNO N° '+num;$('#largeNumber').textContent=num;$('.bottle-no').textContent='N° '+num+' — NOTTURNO';$('#productCounter').textContent=num+' / 03';$$('[data-flavor]').forEach(b=>{let active=+b.dataset.flavor===selected;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',active);let label=b.querySelector('.select-label');if(label)label.textContent=active?'SÉLECTIONNÉ ↗':'CHOISIR ↗'});$('.choice-note').textContent=['Les quais prennent un reflet bleu.','Une lumière verte gagne le port.','La nuit se teinte d’or.'][selected]};$$('[data-flavor]').forEach(b=>b.addEventListener('click',()=>choose(+b.dataset.flavor)));$('#prevProduct').onclick=()=>choose(selected-1);$('#nextProduct').onclick=()=>choose(selected+1);const drawer=$('#chapters');function menu(open){drawer.hidden=!open;$('#menu').setAttribute('aria-expanded',open)}$('#menu').onclick=()=>menu(drawer.hidden);$('#closeMenu').onclick=()=>menu(false);$$('#chapters a').forEach(a=>a.onclick=()=>menu(false));document.addEventListener('keydown',e=>{if(e.key==='Escape')menu(false)});const reveal=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');reveal.unobserve(e.target)}}),{threshold:.12});$$('.reveal').forEach(e=>reveal.observe(e));const sections=[...$$('main section[id]')];const names=['00 — L’INVITATION','01 — LA TRAVERSÉE','02 — LE PASSAGE','03 — LA TENTATION','04 — LE RITUEL','05 — L’ÉVEIL','06 — LA COLLECTION'];function progress(){let p=scrollY/(document.documentElement.scrollHeight-innerHeight);document.documentElement.style.setProperty('--progress',p);let i=0;sections.forEach((s,n)=>{if(s.getBoundingClientRect().top<innerHeight*.5)i=n});$('#chapterLabel').textContent=names[i]}addEventListener('scroll',progress,{passive:true});progress();
function hold(el,onProgress,onDone){let frame,start,running=false,done=false;function stop(){running=false;cancelAnimationFrame(frame)}function begin(e){if(done)return;if(e)e.preventDefault();running=true;start=performance.now();function tick(t){if(!running)return;let p=Math.min((t-start)/1500,1);onProgress(p);if(p===1){done=true;stop();onDone()}else frame=requestAnimationFrame(tick)}frame=requestAnimationFrame(tick)}el.addEventListener('pointerdown',e=>{el.setPointerCapture(e.pointerId);begin(e)});el.addEventListener('pointerup',stop);el.addEventListener('pointercancel',stop);el.addEventListener('keydown',e=>{if((e.key===' '||e.key==='Enter')&&!e.repeat)begin(e)});el.addEventListener('keyup',stop);el.addEventListener('lostpointercapture',stop);return stop}
hold($('#portalHold'),p=>{$('.portal-glow').style.opacity=p;$('#portalHold').style.background=`conic-gradient(#e7d47a ${p*360}deg, #eeece3 0)`},()=>{$('#portalHold').innerHTML='PASSAGE OUVERT<br><span>↓</span>';$('#portalStatus').textContent='Le passage est ouvert. Poursuivez vers les trois tentations.';$('#portalHold').onclick=()=>$('#choice').scrollIntoView({behavior:'smooth'})});hold($('#pourHold'),p=>{document.documentElement.style.setProperty('--fill',p*85+'%');$('.pour-stage').classList.add('pouring');$('#pourStatus').textContent='Prenez votre temps…'},()=>{$('.pour-stage').classList.remove('pouring');$('#pourHold').textContent='VOTRE PIGMENT EST PRÊT ✓';$('#pourStatus').textContent='La nuit peut commencer.'});['pointerup','pointercancel','keyup'].forEach(type=>$('#pourHold').addEventListener(type,()=>$('.pour-stage').classList.remove('pouring')));
let audio,master,playing=false;$('#sound').onclick=()=>{if(!audio){audio=new (window.AudioContext||window.webkitAudioContext)();master=audio.createGain();master.gain.value=0;master.connect(audio.destination);[110,164.81,220].forEach((frequency,i)=>{let o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=frequency;g.gain.value=.022/(i+1);o.connect(g);g.connect(master);o.start()})}audio.resume();playing=!playing;master.gain.setTargetAtTime(playing?1:0,audio.currentTime,.6);$('#sound').innerHTML=playing?'SON ON <span>▂▅▃▆</span>':'SON OFF <span>▂▅▃▆</span>';$('#sound').setAttribute('aria-pressed',playing)};
